SET SCHEMA "BSCL";



CREATE LOCAL TEMPORARY TABLE #INFOREDETERMINADA(
"NombreCorredora" VARCHAR(100)
,"DocumentoIdentidad" VARCHAR(100)
,"IdEmpresa" int
);

INSERT INTO #INFOREDETERMINADA VALUES('CREDICORP','96489000-5',1);


--Cambiar nombre de Empresa

UPDATE  EMP
SET EMP."Nombre" = CONCAT(INFOPRED."NombreCorredora",' CORREDORES DE BOLSA S.A.')
FROM "BSCL.Plataforma.BD::PLA.Empresa" EMP INNER JOIN  #INFOREDETERMINADA INFOPRED
ON INFOPRED."IdEmpresa" = EMP."IdEmpresa";

--Eliminar Imagenes Sistema

UPDATE IMG
SET "Binario" = ''
FROM "BSCL.Plataforma.BD::PLA.Imagenes" IMG 
WHERE "NombreImagen" IN ('LOGO_CORREDOR_LOGIN','LOGO_BOLSA','LOGO_CORREDOR');

--Pisar el socio de negocio para que salgan los comprobantes bien

UPDATE DI
SET DI."DocumentoIdentidad" = '9000-1'
FROM "BSCL.SocioNegocio.BD::PER.DocumentoIdentidad" DI INNER JOIN
#INFOREDETERMINADA INFOPRED  ON INFOPRED."DocumentoIdentidad"= DI."DocumentoIdentidad" ;

UPDATE doc 
SET doc."DocumentoIdentidad" = INFOPRED."DocumentoIdentidad"
FROM "BSCL.SocioNegocio.BD::PER.DocumentoIdentidad" doc
INNER JOIN "BSCL.SocioNegocio.BD::SOC.SocioDeNegocio" soc ON doc."IdPersona" = soc."IdPersona"
INNER JOIN "BSCL.Plataforma.BD::PLA.Empresa" emp ON emp."IdSocioDeNegocio" = soc."IdSocioDeNegocio"
INNER JOIN #INFOREDETERMINADA INFOPRED ON INFOPRED."IdEmpresa"=emp."IdEmpresa";

--Eliminar Nominas

DELETE FROM BSCL."BSCL.Normativa.BD::CAR.Nomina";

--Eliminar Cartolas

DELETE FROM BSCL."BSCL.Normativa.BD::CAR.Cartola";
DELETE FROM BSCL."BSCL.Normativa.BD::CAR.CartolaHistorica";

--Borrar Logo Cartolas

UPDATE BSCL."BSCL.Normativa.BD::CAR.Recurso" SET "Nombre" = CONCAT("Nombre",'_Disabled')
WHERE "Nombre" IN ('LogoCorredora','STI_logotipo') AND "IdPlantilla" IN (
SELECT TOP 1 "IdPlantilla" FROM BSCL."BSCL.Normativa.BD::CAR.Plantilla" ORDER BY "VigenteDesde" DESC
);


--Información del Contratos generales (Se usa en Circulares)

UPDATE CG
SET CG."RazonSocial" =CONCAT(INFOPRED."NombreCorredora",' CORREDORES DE BOLSA S.A.')
,CG."RUT" = INFOPRED."DocumentoIdentidad"
,CG."Direccion" = 'CALLE LA BOLSA'
,CG."Email" = 'CONTACTO@BOLSADESANTIAGO.COM'
,CG."Telefono" = '56-229999999'
,CG."Fax" = '56-229999999'
,CG."Apoderado2" = ''
,CG."Apoderado1" = ''
,CG."DocumentoApoderado1" = ''
,CG."DocumentoApoderado2" = ''
FROM "BSCL.Plataforma.BD::CTT.ContratoDatosGenerales" CG INNER JOIN #INFOREDETERMINADA INFOPRED
ON INFOPRED."IdEmpresa" = CG."IdEmpresa";


