UPDATE  PER
SET PER."RazonSocial" = REPLACE(PER."RazonSocial",'MBI','DEMO')
FROM "BSCL.SocioNegocio.BD::PER.Persona" PER WHERE
PER."IdPersona" NOT IN (SELECT "IdPersona" FROM #EXCLUIR_ELIMINACION_RAZONSOCIAL) 
AND PER."RazonSocial" LIKE('%MBI%');


