UPDATE PER
SET PER."Nombres" = PG."Nombre"
,PER."ApellidoPaterno" = PG."Apellido"
FROM BSCL."BSCL.SocioNegocio.BD::PER.Persona" PER INNER JOIN
#PERSONASGENERADAS PG ON PER."IdPersona" = PG."IdCliente";


